typed_assumptions={r['assumption_id']:r['selected_value'] for r in json.loads((R/'assumptions_register.json').read_text())}
rs=read('assumptions_register.csv')
for r in rs:
 field,why,impact,how=ass[r['assumption_id']]
 r.update(field=field,rationale=why,sensitivity_or_impact=impact,how_to_refine=how,selected_by='Исследователь P10',user_approved='Нет; исследовательское условие в разрешённой области, не решение команды.')
 if r['justified_range_or_UNKNOWN']!='UNKNOWN':
  if r['assumption_id']=='P10-ROUND':r['justified_range_or_UNKNOWN']='При обычном округлении к 0,1 млн разрыв 11,0–11,2 млн; правило округления релизов UNKNOWN.'
  elif r['assumption_id']=='P10-SHARE':r['justified_range_or_UNKNOWN']='0..1 — математическая область только при отсутствии других изменений рынка.'
  elif r['assumption_id']=='P10-SEATS-SJ':r['justified_range_or_UNKNOWN']='UNKNOWN; 100 и 103 — два разных условия, не ожидаемый интервал.'
  elif r['assumption_id']=='P10-NORMALIZE':r['justified_range_or_UNKNOWN']='Единица нормировки; не неизвестный рыночный параметр.'
write('assumptions_register.csv',rs)
json_rows=[{**r,'selected_value':typed_assumptions[r['assumption_id']]} for r in rs]
(R/'assumptions_register.json').write_text(json.dumps(json_rows,ensure_ascii=False,indent=2)+'\n')

